package com.rikkeibank.account.web;import com.rikkeibank.account.domain.*;import com.rikkeibank.account.service.*;import com.rikkeibank.common.api.BusinessException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
public final class AccountControllers{private AccountControllers(){}
 @RestController @RequestMapping("/api/account-types")@PreAuthorize("hasRole('ADMIN')")public static class TypeController{private final AccountTypeService s;public TypeController(AccountTypeService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)AccountType create(@Valid @RequestBody TypeRequest r){return s.create(r.code(),r.name(),r.minimumBalance());}@GetMapping Page<AccountType>list(Pageable p){return s.list(p);}@GetMapping("/{id}")AccountType get(@PathVariable UUID id){return s.get(id);}@PutMapping("/{id}")AccountType update(@PathVariable UUID id,@Valid @RequestBody TypeRequest r){return s.update(id,r.code(),r.name(),r.minimumBalance(),r.active());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){s.delete(id);}public record TypeRequest(@NotBlank String code,@NotBlank String name,@PositiveOrZero BigDecimal minimumBalance,boolean active){}}
 @RestController @RequestMapping("/api/accounts")public static class AccountController{private final AccountService s;public AccountController(AccountService s){this.s=s;}@PostMapping @PreAuthorize("hasRole('ADMIN')")@ResponseStatus(HttpStatus.CREATED)Account create(@Valid @RequestBody Create r){return s.create(r.customerId(),r.accountTypeId(),r.initialBalance());}@GetMapping @PreAuthorize("hasRole('ADMIN')")Page<Account>list(Pageable p){return s.list(p);}@GetMapping("/me")@PreAuthorize("hasRole('CUSTOMER')")List<Account>mine(@AuthenticationPrincipal Jwt jwt){return s.byCustomer(UUID.fromString(jwt.getClaimAsString("customerId")));}@GetMapping("/{id}")@PreAuthorize("hasRole('ADMIN') or @accountAuthorization.owns(#id,authentication.tokenAttributes['customerId'])")Account get(@PathVariable UUID id){return s.get(id);}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")Account update(@PathVariable UUID id,@Valid @RequestBody Update r){return s.update(id,r.accountTypeId(),r.status());}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){s.delete(id);}public record Create(@NotNull UUID customerId,@NotNull UUID accountTypeId,@PositiveOrZero BigDecimal initialBalance){}public record Update(@NotNull UUID accountTypeId,@NotNull Account.Status status){}}
 @RestController @RequestMapping("/internal/accounts")public static class InternalController{private final AccountService s;private final String key;public InternalController(AccountService s,@Value("${security.internal-key}")String k){this.s=s;key=k;}@PostMapping("/{id}/debit")Account debit(@RequestHeader("X-Internal-Key")String k,@PathVariable UUID id,@Valid @RequestBody Movement r){guard(k);return s.debit(r.operationId(),id,r.customerId(),r.amount());}@PostMapping("/{id}/credit")Account credit(@RequestHeader("X-Internal-Key")String k,@PathVariable UUID id,@Valid @RequestBody Movement r){guard(k);return s.credit(r.operationId(),id,r.amount());}@PostMapping("/{id}/refund")Account refund(@RequestHeader("X-Internal-Key")String k,@PathVariable UUID id,@Valid @RequestBody Movement r){guard(k);return s.refund(r.operationId(),id,r.amount());}private void guard(String k){if(!key.equals(k))throw new BusinessException(HttpStatus.FORBIDDEN,"INVALID_INTERNAL_KEY","Invalid service credential");}public record Movement(@NotNull UUID operationId,UUID customerId,@Positive BigDecimal amount){}}
}

